const rawExtraction = $('Raw Extraction - Market Research').first().json.output;
const coreSkillsRaw = $('Raw Extraction - Core Skills').first().json.output;
const decisions = $('Binary Classifier').first().json.output?.decisions ?? $input.first().json.decisions;

const CORE_SKILLS_THRESHOLD = 2; // change this to adjust

const technology_list = [
  ...new Set(
    decisions
      .filter(d => d.valid === true)
      .map(d => d.item)
  )
];

const city_list = rawExtraction?.city_list ?? [];
const role_list = JSON.stringify(rawExtraction?.role_list ?? []);

const skillCounts = coreSkillsRaw?.skill_counts ?? [];
const core_skills_list = JSON.stringify(
  skillCounts
    .filter(s => s.count >= CORE_SKILLS_THRESHOLD)
    .sort((a, b) => b.count - a.count)
    .map(s => s.technology)
);;

return [{ json: { technology_list, city_list, role_list, core_skills_list } }];

// Detects plain-text section headers and promotes them to ## markdown headers.
// Idempotent: CVs already using ## are returned unchanged.
function normalizeCV(text) {
  if (!text) return text;
  if (/^##\s/m.test(text)) return text; // already normalized

  const lines = text.replace(/\r\n/g, '\n').replace(/\r/g, '\n').split('\n');
  const result = [];
  let seenFirstBlank = false;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const trimmed = line.trim();
    const prevTrimmed = i > 0 ? lines[i - 1].trim() : '';

    if (trimmed === '') {
      seenFirstBlank = true;
      result.push(line);
      continue;
    }

    // Personal info block (name, title, contact) — never convert
    if (!seenFirstBlank) {
      result.push(line);
      continue;
    }

    const isShort      = trimmed.length < 65;
    const prevIsBlank  = prevTrimmed === '';
    const noDate       = !/\d{2}\.\d{4}/.test(trimmed);
    const noContact    = !/[·|@]/.test(trimmed) && !trimmed.includes('http');
    const noBullet     = !/^[-*\t]/.test(trimmed) && !/^\d+\./.test(trimmed);
    const noBold       = !trimmed.startsWith('**');
    const noParenStart = !trimmed.startsWith('(');

    if (isShort && prevIsBlank && noDate && noContact && noBullet && noBold && noParenStart) {
      result.push('## ' + trimmed);
    } else {
      result.push(line);
    }
  }

  return result.join('\n');
}

const body = $("Webhook").first().json.body;
const isUpdate = !!body.profile_id;

// CREATE PROFILE MODE: Validate required fields
if (!isUpdate) {
  const required = ['full_name', 'cv_text', 'market_research', 'career_target'];
  for (const field of required){
    if (!body[field] || body[field].toString().trim() === '') {
      return [{
        json: {
          valid: false,
          error: 'missing_required_field',
          message: `${field} is required`
        }
      }];
    }
  } 
}

// UPDATE PROFILE MODE: profile_id must be a positive integer
if (isUpdate && (!Number.isInteger(Number(body.profile_id)) || Number(body.profile_id) <= 0)) {
  return [{
    json: {
      valid: false,
      error: 'invalid_profile_id',
      message: 'profile_id must be a positive integer'
    }
  }];
}
// For UPDATE branches
const cvTextProvided = isUpdate && !!body.cv_text && body.cv_text.trim() !== '';
const marketResearchProvided = isUpdate && !!body.market_research && body.market_research.trim() !== '';


return [{
  json: {
    valid: true,
    is_update: isUpdate,
    cv_text_provided: cvTextProvided,
    market_research_provided: marketResearchProvided,
    profile_id: isUpdate ? Number(body.profile_id) : null,
    // Fields for profile
    full_name: body.full_name?.trim() || null,
    email: body.email?.trim() || null,
    phone: body.phone?.trim() || null,
    location: body.location?.trim() || null,
    linkedin_url: body.linkedin_url?.trim() || null,
    github_url: body.github_url?.trim() || null,
    website_url: body.website_url?.trim() || null,
    avatar_url: body.avatar_url?.trim() || null,
    notes: body.notes?.trim() || null,
    // Fields for candidate_context
    cv_text: normalizeCV(body.cv_text?.trim()) || null,
    cv_language: body.cv_language?.trim() || null,
    market_research: body.market_research?.trim() || null,
    career_target: body.career_target?.trim() || null
  }
}];

const validated = $('Validate Inputs').first().json;

// Safely capture hash and language — these nodes only run in UPDATE+cv_text case
let cv_hash = null;
try { cv_hash = $('Hash CV').first().json.new_hash; } catch(e) {}

let cv_language = null;
try { cv_language = $('Detect CV Language').first().json.cv_language; } catch(e) {}

if (validated.is_update) {
  return [{ json: { 
    profile_id: validated.profile_id,
    cv_hash,
    cv_language
  }}];
} else {
  return [{ json: { 
    profile_id: $('CREATE Profile').first().json.id,
    cv_hash,
    cv_language
  }}];
}

// Flat items
const rows = $('Fetch Full Context').all();
const ctx = {};
for (const row of rows) {
  ctx[row.json.key] = row.json.value;
}
// add profile id
ctx.profile_id = $('Set Profile ID').first().json.profile_id;

return [{ json: ctx }];

function escapeRegex(str) {
  return str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

const llmOutput  = $('Extract Candidate Profile').first().json.output;
const profile    = llmOutput.candidate_profile;
const roleScores = llmOutput.role_type_scores;

const marketResearch = $('Build Context Item').first().json.market_research || '';

// If market_research explicitly mentions the home city as a work location
// but the LLM omitted it from commute_options, add it.
const homeCity      = (profile.home_location || '').split(',')[0].trim();
let commuteOptions  = profile.commute_options || '';

if (homeCity) {
  const mentionedInMarket = new RegExp(
    '\\b' + escapeRegex(homeCity) + '\\b', 'i'
  ).test(marketResearch);

  const includedInCommute = new RegExp(
    '\\b' + escapeRegex(homeCity) + '\\b', 'i'
  ).test(commuteOptions);

  if (mentionedInMarket && !includedInCommute) {
    commuteOptions = `${homeCity} (~0h, home city) | ${commuteOptions}`;
  }
}

return [{
  json: {
    candidate_profile: {
      ...profile,
      commute_options: commuteOptions,
    },
    role_type_scores: JSON.stringify(roleScores),
  }
}];

const cvText = $('Validate Inputs').first().json.cv_text;
const cvTextProvided = $("Validate Inputs").first().json.cv_text_provided;
const isUpdate = $('Validate Inputs').first().json.is_update;
const shouldDetectLanguage = cvTextProvided || !isUpdate;

function detectLanguage(text) {
  const input = String(text || "").trim();

  if (!input) {
    return {
      language: "unknown",
      confidence: 0,
      scores: { german: 0, english: 0 }
    };
  }

  const lower = input.toLowerCase();

  // Common markers
  const germanWords = [
    "der", "die", "das", "und", "ist", "nicht", "ich", "du", "wir", "ihr",
    "sie", "mit", "für", "auf", "ein", "eine", "einer", "einem", "den",
    "dem", "des", "wie", "was", "aber", "auch", "noch", "nur", "schon",
    "wenn", "dann", "oder", "hat", "haben", "war", "waren", "zum", "zur"
  ];

  const englishWords = [
    "the", "and", "is", "not", "i", "you", "we", "they", "with", "for",
    "on", "a", "an", "this", "that", "of", "to", "in", "as", "but",
    "also", "still", "only", "already", "if", "then", "or", "has", "have",
    "had", "was", "were", "be", "are", "from", "it"
  ];

  let germanScore = 0;
  let englishScore = 0;

  // Strong German hints
  if (/[äöüß]/.test(lower)) germanScore += 4;
  if (/\b(nicht|ich|und|für|mit|eine|einer|einem|der|die|das)\b/.test(lower)) germanScore += 3;
  if (/(sch|ung|keit|lich|chen)\b/.test(lower)) germanScore += 2;

  // Strong English hints
  if (/\b(the|and|with|this|that|have|from|are|was|were)\b/.test(lower)) englishScore += 3;
  if (/\b(ing|tion|ness|ment)\b/.test(lower)) englishScore += 1;

  // Count stopwords
  for (const word of germanWords) {
    const matches = lower.match(new RegExp(`\\b${word}\\b`, "g"));
    if (matches) germanScore += matches.length;
  }

  for (const word of englishWords) {
    const matches = lower.match(new RegExp(`\\b${word}\\b`, "g"));
    if (matches) englishScore += matches.length;
  }

  let language = "unknown";
  if (germanScore > englishScore) language = "de";
  else if (englishScore > germanScore) language = "en";

  const total = germanScore + englishScore;
  const confidence = total === 0
    ? 0
    : Number((Math.max(germanScore, englishScore) / total).toFixed(2));

  return {
    language,
    confidence,
    scores: {
      german: germanScore,
      english: englishScore
    }
  };
}

return [{ 
  json: { 
    cv_language: shouldDetectLanguage ? detectLanguage(cvText).language : null
  } 
}]
